import React, { useState } from "react";
import API from "../api";

export default function Login({ setToken }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(false);

  const submit = async (type) => {
    setLoading(true);
    setMessage("");

    try {
      if (type === "register") {
        await API.post("/auth/register", { username, password });
        setMessage("Пользователь создан. Теперь можно войти.");
      } else {
        const res = await API.post("/auth/login", { username, password });
        setToken(res.data.token);
      }
    } catch (err) {
      setMessage(err.response?.data?.msg || "Ошибка запроса");
    } finally {
      setLoading(false);
    }
  };

  return (
    <section className="auth">
      <div className="panel">
        <h1>IT Infrastructure System</h1>
        <h2>Вход в систему</h2>

        <label>
          Логин
          <input
            value={username}
            placeholder="Введите логин"
            onChange={(e) => setUsername(e.target.value)}
          />
        </label>

        <label>
          Пароль
          <input
            value={password}
            placeholder="Введите пароль"
            type="password"
            onChange={(e) => setPassword(e.target.value)}
          />
        </label>

        <div className="actions">
          <button disabled={loading} onClick={() => submit("login")}>
            Войти
          </button>
          <button disabled={loading} className="secondary" onClick={() => submit("register")}>
            Регистрация
          </button>
        </div>

        {message && <p className="message">{message}</p>}
      </div>
    </section>
  );
}
